const A={products:[],orders:[],settings:null,banners:[],placements:[],blogs:[],leads:[],api:null,payments:null,user:null,stories:[]};
// Read-only shared reference for additive admin enhancements. Keeping one state
// object avoids a second products request and leaves the established loaders in
