window.dropbeatAdminState=A;
const INR = new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0});
const SOCIAL_DEFAULT_URLS={instagram:'https://www.instagram.com',facebook:'https://www.facebook.com',threads:'https://www.threads.net',youtube:'https://www.youtube.com',telegram:'https://telegram.org',snapchat:'https://www.snapchat.com',x:'https://www.x.com',linkedin:'https://www.linkedin.com',whatsapp:'https://wa.me/919381521966'};
function isConfirmedAdminAuthError(status,data){const m=String(data?.error||'').toLowerCase();return Number(status)===401&&(m.includes('admin login required')||m.includes('invalid admin login')||m.includes('unauthorized')||m.includes('session expired'));}
const ucAdminGetCache=new Map(),ucAdminGetInflight=new Map();let ucAdminCacheGeneration=0;
const ucAdminCacheableGet=path=>new Set(['/api/admin/products','/api/admin/pages','/api/admin/settings','/api/admin/social-automations','/api/admin/lead-nurture-automations']).has(String(path||'').split('?')[0]);
const ucAdminClone=value=>{try{return typeof structuredClone==='function'?structuredClone(value):JSON.parse(JSON.stringify(value));}catch(_){return value;}};
function ucAdminInvalidateApiCache(){window.DropBeatDataCache?.invalidate('admin:');ucAdminCacheGeneration++;ucAdminGetCache.clear();ucAdminGetInflight.clear();}
window.ucAdminInvalidateApiCache=ucAdminInvalidateApiCache;
window.ucAdminHasCachedApi=path=>{const hit=ucAdminGetCache.get(String(path||''));return !!(hit&&hit.expires>Date.now());};
async function api(path, opts={}){
  const method=String(opts.method||'GET').toUpperCase(),key=String(path||''),cacheable=method==='GET'&&ucAdminCacheableGet(key);
  if(cacheable){const hit=ucAdminGetCache.get(key);if(hit&&hit.expires>Date.now())return ucAdminClone(hit.data);if(ucAdminGetInflight.has(key))return ucAdminClone(await ucAdminGetInflight.get(key));}
  if(method!=='GET')ucAdminInvalidateApiCache();
  const requestGeneration=ucAdminCacheGeneration;
  const request=(async()=>{const isFormData=typeof FormData!=='undefined'&&opts.body instanceof FormData;const base={credentials:'same-origin',cache:'no-store'},requestOptions=isFormData?{...base,...opts,headers:{...(opts.headers||{})}}:{...base,headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts};const res=await fetch(path,requestOptions);const data=await res.json().catch(()=>({}));if(!res.ok){if(isConfirmedAdminAuthError(res.status,data))showLogin();const error=new Error(data.error||'Request failed');error.status=res.status;error.responseData=data;error.diagnostic=data.diagnostic||null;error.recovery=data.recovery||data.diagnostic?.recovery||null;error.validationErrors=Array.isArray(data.validationErrors)?data.validationErrors:[];throw error;}if(cacheable&&requestGeneration===ucAdminCacheGeneration)ucAdminGetCache.set(key,{data:ucAdminClone(data),expires:Date.now()+60000});return data;})();
  if(cacheable)ucAdminGetInflight.set(key,request);
  try{return ucAdminClone(await request);}finally{if(cacheable)ucAdminGetInflight.delete(key);}
}
// V1.50 reuses the established transport/authentication and cache invalidation.
const ucAdminTransportApi=api;
api=async function(path,opts={}){
  const cache=window.DropBeatDataCache,method=String(opts.method||'GET').toUpperCase(),key=String(path||'');
  if(cache&&method==='GET'&&ucAdminCacheableGet(key)&&!opts.signal){
    const force=Boolean(opts.force)||/[?&](?:refresh|force)=(?:1|true)(?:&|$)/.test(key)||opts.cache==='reload';
    return cache.query('admin:'+key,()=>{if(force)ucAdminGetCache.delete(key);return ucAdminTransportApi(path,opts);},{staleTime:60000,maxAge:300000,force,onUpdate:data=>{
      if(key.split('?')[0]==='/api/admin/products'&&Array.isArray(data.products)){
        A.products=data.products;
        if(qs('#products')?.offsetParent&&!document.querySelector('.modal.open,.db138-inline-form-open')&&!document.activeElement?.matches('input,textarea,select'))window.renderProducts?.();
      }
    }});
  }
  const data=await ucAdminTransportApi(path,opts);
  // The settings API already returns its validated, normalized saved object.
  // Reuse it instead of doing a redundant post-save GET. Other writes keep
  // their authoritative reload when the server returns only an id/ok flag.
  if(cache&&method!=='GET'&&key.split('?')[0]==='/api/admin/settings'&&data?.settings){
    const snapshot={settings:data.settings};cache.set('admin:/api/admin/settings',snapshot);
    ucAdminGetCache.set('/api/admin/settings',{data:ucAdminClone(snapshot),expires:Date.now()+60000});
  }
  return data;
};
function scheduleAdminPrefetch(){
  if(window.__ucAdminPrefetchScheduled||navigator.connection?.saveData||/2g/.test(navigator.connection?.effectiveType||''))return;
  window.__ucAdminPrefetchScheduled=true;
  const paths=['/api/admin/settings','/api/admin/products','/api/admin/pages','/api/admin/social-automations','/api/admin/lead-nurture-automations'];let index=0;
  const next=()=>{if(index>=paths.length||document.hidden)return;const path=paths[index++];api(path).then(data=>{if(path==='/api/admin/settings'&&data?.settings){A.settings=data.settings;window.__ucLatestSettings=A.settings;window.applyDropBeatAdminBrand?.();}}).catch(()=>{}).finally(()=>setTimeout(next,1100));};
  const begin=()=>setTimeout(next,900);
  if('requestIdleCallback'in window)requestIdleCallback(begin,{timeout:2200});else setTimeout(begin,1400);
}
function qs(s){return document.querySelector(s)} function qsa(s){return [...document.querySelectorAll(s)]}
function esc(s=''){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function msg(sel,text,type='notice'){const el=qs(sel);if(el)el.innerHTML=`<div class="${type}">${esc(text)}</div>`;}
function settleAdminAuth(mode){const root=document.documentElement,shell=qs('#dropbeatAuthShell');root.classList.remove('dropbeat-auth-pending','dropbeat-auth-guest','dropbeat-admin-ready');if(mode==='admin')root.classList.add('dropbeat-admin-ready');if(mode==='guest')root.classList.add('dropbeat-auth-guest');if(shell)shell.hidden=true;}
function showLogin(){if(location.pathname.startsWith('/admin')){location.replace(`/login?next=${encodeURIComponent('/admin/')}`);return;}const login=qs('#loginOverlay'),app=qs('#adminApp');if(login)login.hidden=false;if(app)app.hidden=true;settleAdminAuth('guest');}
function showAdmin(){const login=qs('#loginOverlay'),app=qs('#adminApp'),wasHidden=!app||app.hidden;if(login)login.hidden=true;if(app)app.hidden=false;settleAdminAuth('admin');if(wasHidden)queueMicrotask(()=>document.dispatchEvent(new CustomEvent('dropbeat:admin-ready')));}
function showAuthProblem(error){const shell=qs('#dropbeatAuthShell'),title=qs('#dropbeatAuthShellTitle'),text=qs('#dropbeatAuthShellText');document.documentElement.classList.add('dropbeat-auth-pending');if(shell)shell.hidden=false;if(title)title.textContent='Admin session check needs another try';if(text)text.innerHTML=`${esc(error?.message||'The secure session service is temporarily unavailable.')} <button class="btn compact" type="button" onclick="location.reload()" style="margin:16px auto 0">Retry securely</button>`;}
async function adminSessionRequest(){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{return await api('/api/admin/auth/me',{signal:controller.signal});}catch(error){if(error?.name==='AbortError')throw new Error('Admin session check timed out. Please retry securely.');throw error;}finally{clearTimeout(timer);}}
async function checkAuth(){let last=null;for(let i=0;i<3;i++){try{const res=await adminSessionRequest();A.user=res.user;showAdmin();return true;}catch(e){last=e;if(Number(e?.status)===401){showLogin();return false;}const m=String(e?.message||'').toLowerCase();if(!(m.includes('temporarily busy')||m.includes('temporarily unavailable')||m.includes('internal error')||m.includes('d1_error')||Number(e?.status)>=500))break;if(i<2)await new Promise(r=>setTimeout(r,180*(i+1)));}}if(Number(last?.status)===401)showLogin();else showAuthProblem(last);return false;}
async function loginAdmin(e){e.preventDefault();const submit=e.submitter||e.target.querySelector('button[type=\"submit\"]');if(submit)submit.disabled=true;try{const res=await fetch('/api/admin/auth/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))});const contentType=String(res.headers.get('content-type')||'');const data=contentType.includes('application/json')?await res.json().catch(()=>({})):{};if(!res.ok)throw new Error(data.error||`Admin login request failed (${res.status}). Please refresh once and try again.`);msg('#loginMsg','Login successful. Loading dashboard.');const ok=await checkAuth();if(!ok)throw new Error('Login was accepted, but the new admin session could not be verified. Please try again.');qsa('.nav button').forEach(b=>b.onclick=()=>tab(b.dataset.tab));const q=new URLSearchParams(location.search),initial=tab(q.get('open')==='comments'?'blogComments':'dashboard');Promise.resolve(initial).catch(()=>{}).finally(scheduleAdminPrefetch);}catch(err){msg('#loginMsg',err.message||'Login failed','error');}finally{if(submit)submit.disabled=false;}}
function googleLoginNotice(){location.href='/login';}
async function logoutAdmin(){await fetch('/api/admin/auth/logout',{method:'POST'}).catch(()=>{});showLogin();}
function tab(id){qsa('.panel').forEach(p=>p.classList.remove('active'));qsa('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));qs('#'+id)?.classList.add('active');if(window['load_'+id])return window['load_'+id]();}
function countChars(input,id,max){const el=qs('#'+id);if(!el)return;const n=String(input.value||'').length;el.textContent=`${n} / ${max} characters`;el.classList.toggle('count-warning',n>max-10);}
async function load_dashboard(){
  const res=await api('/api/admin/dashboard');const s=res.stats||{};
  const set=(sel,val)=>{const el=qs(sel);if(el)el.textContent=val;};
  set('#statOrders',s.orders||0);set('#statPaid',s.paid||0);set('#statFailed',s.failed||0);set('#statRevenue',INR.format((s.revenue_paise||0)/100));
  set('#statPendingOrders',s.pendingOrders||0);set('#statExistingOrders',s.existingOrders||0);set('#statCancelledOrders',s.cancelledOrders||0);set('#statCancelledSubscriptions',s.cancelledSubscriptions||0);
  set('#statTotalLeads',s.totalLeads||0);set('#statHotLeads',s.hotLeads||0);set('#statActiveSubs',s.activeSubscriptions||0);set('#statRecentLeads',s.recentLeads||0);
  set('#statTodayFollowups',s.todayFollowups||0);set('#statTomorrowFollowups',s.tomorrowFollowups||0);set('#statDueFollowups',s.totalFollowupsDue||0);set('#statInquiries',s.inquiries||0);
  set('#statPendingCollections',s.pendingCollections||0);set('#statPendingCollectionsValue',`Total balance due - ${INR.format((s.pendingCollectionsPaise||0)/100)}`);
  set('#statTodayRevenue',INR.format((s.todayRevenuePaise||0)/100));set('#statTodayPayments',`${s.todayPayments||0} payments today`);
  set('#statVisitors',s.websiteVisitors||0);set('#statRepeatVisitors',s.repeatVisitors||0);set('#statTopSource',s.topSource||'Direct / unknown');
}
