async function openDashboardList(type){const res=await api('/api/admin/dashboard-list?type='+encodeURIComponent(type));const title={totalLeads:'Total Leads',hotLeads:'Hot Leads',activeSubscriptions:'Active Subscriptions',recentLeads:'Recent Leads',pendingCollections:'Pending Collections'}[type]||'Dashboard List';qs('#listModalTitle').textContent=title;const rows=res.rows||[];qs('#dashboardListBox').innerHTML=rows.length?`<div class="list-grid">${rows.map(r=>`<div class="lead-card"><h3>${esc(r.name||r.customer_name||r.order_id||'-')}</h3><p class="muted">${esc(r.phone||r.customer_phone||'')} ${r.email||r.customer_email?`• ${esc(r.email||r.customer_email)}`:''}</p>${r.message?`<p>${esc(r.message)}</p>`:''}${r.amount_paise?`<p><strong>${INR.format(r.amount_paise/100)}</strong></p>`:''}<small>${esc(r.status||'')} ${r.payment_status?`• ${esc(r.payment_status)}`:''}</small></div>`).join('')}</div>`:'<div class="notice">No records found yet.</div>';qs('#listModal').classList.add('open');}
async function load_products(){const res=await api('/api/admin/products');A.products=res.products||[];renderProducts();}
function renderProducts(){qs('#productTable').innerHTML=`<table class="table"><thead><tr><th><input type="checkbox" onchange="qsa('[data-pick-product]').forEach(x=>x.checked=this.checked)"></th><th>Plan / Offer</th><th>Price</th><th>Status</th><th>Images</th><th>Actions</th></tr></thead><tbody>${A.products.map(p=>`<tr><td><input type="checkbox" data-pick-product value="${p.id}"></td><td><strong>${esc(p.name)}</strong><br><small>${esc(p.sku)} / ${esc(p.slug)}</small><br><small>${esc(p.short_description||'')}</small></td><td><s>${INR.format((p.regular_price_paise||0)/100)}</s><br><strong>${INR.format((p.offer_price_paise||0)/100)}</strong></td><td><span class="status ${esc(p.status)}">${esc(p.status)}</span></td><td>${(p.images||[]).slice(0,3).map(i=>`<img class="preview-img" src="${esc(i.public_url)}">`).join('')}<br><small>${(p.images||[]).length}/3 images</small></td><td><button class="btn small" onclick="editProductById(${p.id})">Edit</button> <button class="btn secondary small" onclick="openMedia(${p.id})">Images</button></td></tr>`).join('')}</tbody></table>`;}
function newProduct(){qs('#productModalTitle').textContent='Add New Plan / Offer';qs('#productId').value='';qs('#productForm').reset();qs('#productModal').classList.add('open');}
function editProductById(id){const p=A.products.find(x=>x.id===id);if(p)editProduct(p);}
function editProduct(p){qs('#productModalTitle').textContent='Edit Plan / Offer';qs('#productId').value=p.id;['sku','name','slug','short_description','description','badge','eligibility','status','sort_order'].forEach(k=>{const el=qs(`[name="${k}"]`);if(el)el.value=p[k]??''}); const rp=qs('[name="regular_price_rupees"]'); if(rp)rp.value=Math.round((p.regular_price_paise||0)/100); const op=qs('[name="offer_price_rupees"]'); if(op)op.value=Math.round((p.offer_price_paise||0)/100);qs('[name="features_json"]').value=(p.features||[]).join('\n');qs('#productModal').classList.add('open');}
async function saveProduct(e){e.preventDefault();const fd=new FormData(e.target);const payload=Object.fromEntries(fd.entries());payload.id=qs('#productId').value||undefined;payload.features=String(payload.features_json||'').split('\n').map(x=>x.trim()).filter(Boolean);delete payload.features_json;payload.regular_price_rupees=Number(payload.regular_price_rupees||0);payload.offer_price_rupees=Number(payload.offer_price_rupees||0);payload.regular_price_paise=Math.round(payload.regular_price_rupees*100);payload.offer_price_paise=Math.round(payload.offer_price_rupees*100);payload.sort_order=Number(payload.sort_order||0);await api('/api/admin/products',{method:payload.id?'PUT':'POST',body:JSON.stringify(payload)});qs('#productModal').classList.remove('open');await load_products();}
