async function loadProductMedia(productId){const res=await api('/api/admin/media?product_id='+encodeURIComponent(productId));const box=qs('#currentProductMedia');box.innerHTML=`<h3>Current scrolling images (${(res.images||[]).length}/3)</h3>${(res.images||[]).length?`<div class="media-grid">${res.images.map(i=>`<div class="media-card"><img src="${esc(i.public_url)}" alt="${esc(i.alt_text||'')}"><small>${esc(i.alt_text||'No alt text')}</small><button class="btn danger small" onclick="removeProductImage(${i.id},${productId})">Remove</button></div>`).join('')}</div>`:'<div class="notice">No uploaded product images yet. Static default image may still appear on the website.</div>'}`;}
