async function bulkImport(){const file=qs('#bulkFile').files[0];if(!file)return alert('Select CSV first');const text=await file.text();const rows=parseCSV(text);const res=await api('/api/admin/import-products',{method:'POST',body:JSON.stringify({rows})});qs('#bulkResult').innerHTML=`<div class="notice">Created: ${res.created}, Updated: ${res.updated}, Errors: ${res.errors.length}</div>`;await load_products();}
function parseCSV(text){const lines=text.split(/\r?\n/).filter(Boolean);const headers=lines.shift().split(',').map(h=>h.trim());return lines.map(line=>{const cols=line.match(/("[^"]*"|[^,]+)/g)||[];const o={};headers.forEach((h,i)=>o[h]=(cols[i]||'').replace(/^"|"$/g,'').trim());return o;});}
async function load_orders(status=''){const res=await api('/api/admin/orders'+(status?`?status=${status}`:''));A.orders=res.orders||[];qs('#ordersTable').innerHTML=`<table class="table"><thead><tr><th>Order</th><th>Customer</th><th>Amount</th><th>Status</th><th>Payment</th><th>Subscription</th><th>Actions</th></tr></thead><tbody>${A.orders.map(o=>`<tr><td><strong>${esc(o.order_id)}</strong><br><small>${esc(o.created_at)}</small></td><td>${esc(o.customer_name||'')}<br><small>${esc(o.customer_phone||'')}</small><br><small>${esc(o.customer_email||'')}</small></td><td>${INR.format((o.amount_paise||0)/100)}</td><td><span class="status ${esc(o.status)}">${esc(o.status)}</span></td><td>${esc(o.payment_status||'')}</td><td><small>${esc(o.gateway_subscription_id||'No subscription ID yet')}</small></td><td><button class="btn small" onclick="openOrderEditor('${esc(o.order_id)}')">Edit / Update</button></td></tr>`).join('')}</tbody></table>`;}
