async function load_banners(){const res=await api('/api/admin/banners');A.banners=res.banners||[];qs('#bannerTable').innerHTML=`<table class="table"><thead><tr><th>Home Page Banner</th><th>Image</th><th>Link</th><th>Status</th><th>Actions</th></tr></thead><tbody>${A.banners.map(b=>`<tr><td><strong>${esc(b.title)}</strong><br>${esc(b.subtitle||'')}<br><small>Sort: ${b.sort_order||0}</small></td><td><img class="preview-img" src="${esc(b.desktop_image_url||'/assets/gym-hero.jpg')}"></td><td>${esc(b.link_type)}: ${esc(b.link_value||'')}</td><td><span class="status ${b.visible?'active':'draft'}">${b.visible?'visible':'hidden'}</span></td><td><button class="btn small" onclick="editBanner(${b.id})">Edit</button> <button class="btn danger small" onclick="deleteBanner(${b.id})">Delete</button></td></tr>`).join('')}</tbody></table>`;}
