function renderStories(){qs('#storyTable').innerHTML=A.stories.length?`<table class="table"><thead><tr><th>Story</th><th>Preview</th><th>Status</th><th>Actions</th></tr></thead><tbody>${A.stories.map(s=>`<tr><td><strong>${esc(s.title||'Untitled story')}</strong><br><small>${esc(s.platform)} • ${esc(s.url)}</small></td><td><img class="story-thumb" src="${esc(s.thumbnail_url||'/assets/product-generic.svg')}"></td><td><span class="status ${esc(s.status)}">${esc(s.status)}</span></td><td><button class="btn small" onclick="editStory(${s.id})">Edit</button> <button class="btn danger small" onclick="deleteStory(${s.id})">Delete</button></td></tr>`).join('')}</tbody></table>`:'<div class="notice">No success stories added yet.</div>';}
function editStory(id){const s=A.stories.find(x=>x.id===id);if(!s)return;const f=qs('#successStories form');f.id.value=s.id;f.title.value=s.title||'';f.url.value=s.url||'';f.thumbnail_url.value=s.thumbnail_url||'';f.status.value=s.status||'active';f.sort_order.value=s.sort_order||0;}
async function saveSuccessStory(e){e.preventDefault();const payload=Object.fromEntries(new FormData(e.target).entries());await api('/api/admin/success-stories',{method:'POST',body:JSON.stringify(payload)});e.target.reset();msg('#storyMsg','Success story saved.');await load_successStories();}
async function deleteStory(id){if(!confirm('Delete this success story?'))return;await api('/api/admin/success-stories?id='+encodeURIComponent(id),{method:'DELETE'});await load_successStories();}
async function load_settings(){const res=await api('/api/admin/settings');A.settings=res.settings;window.__ucLatestSettings=A.settings;const s=A.settings;['siteName','tagline','frontendTheme','primaryColor','accentColor','logoUrl','faviconUrl','whatsappNumber'].forEach(k=>{const el=qs(`#settings [name="${k}"]`);if(el)el.value=s[k]||''});window.applyDropBeatAdminBrand?.();}
async function load_socials(){if(!A.settings)await load_settings();renderSocials(A.settings.socials||[]);}
async function load_tracking(){if(!A.settings)await load_settings();const s=A.settings;['googleAnalyticsMeasurementId','googleTagManagerId','metaPixelId','searchConsoleVerification','snapchatPixelId','xPixelId','linkedinPartnerId','pinterestTagId','redditPixelId','bingWebmasterVerification','yahooSearchVerification','yandexVerification'].forEach(k=>{const el=qs(`#tracking [name="${k}"]`);if(el)el.value=s[k]||''});}
function renderSocials(socials){const defaults=[{key:'instagram',label:'Instagram'},{key:'facebook',label:'Facebook'},{key:'threads',label:'Threads'},{key:'youtube',label:'YouTube'},{key:'telegram',label:'Telegram'},{key:'snapchat',label:'Snapchat'},{key:'x',label:'X'},{key:'linkedin',label:'LinkedIn'},{key:'whatsapp',label:'WhatsApp',enabled:true}];const list=defaults.map(d=>({...d,...(socials.find(s=>s.key===d.key)||{})}));qs('#socialRows').innerHTML=list.map((s,i)=>`<div class="toggle-row"><div class="field"><label>${esc(s.label)}</label><input name="social_${i}_url" value="${esc(s.url||'')}" placeholder="Paste ${esc(s.label)} profile link"><input type="hidden" name="social_${i}_key" value="${esc(s.key)}"><input type="hidden" name="social_${i}_label" value="${esc(s.label)}"><small class="hint">Default testing link: ${esc(SOCIAL_DEFAULT_URLS[s.key]||'#')}</small></div><div class="toggle-control"><span>Show</span><label class="switch"><input type="checkbox" name="social_${i}_enabled" ${s.enabled?'checked':''}><span class="slider"></span></label></div></div>`).join('');}
async function uploadBrandAsset(file){if(!file||!file.size)return '';if(file.size>300*1024)throw new Error('Logo/Favicon upload must be 300 KB or less.');const fd=new FormData();fd.append('file',file);const res=await fetch('/api/admin/media',{method:'POST',body:fd});const data=await res.json();if(!res.ok)throw new Error(data.error||'Upload failed');return data.url;}
async function saveSettings(e){e.preventDefault();const fd=new FormData(e.target);const base=Object.fromEntries(fd.entries());const logoUploaded=await uploadBrandAsset(fd.get('logoFile'));const faviconUploaded=await uploadBrandAsset(fd.get('faviconFile'));const payload={siteName:base.siteName,tagline:base.tagline,frontendTheme:base.frontendTheme||A.settings?.frontendTheme||'dropbeat',primaryColor:base.primaryColor,accentColor:base.accentColor,logoUrl:logoUploaded||base.logoUrl,faviconUrl:faviconUploaded||base.faviconUrl,whatsappNumber:base.whatsappNumber,marqueeTabTitleEnabled:!!e.target.querySelector('[name="marqueeTabTitleEnabled"]')?.checked};A.settings={...(A.settings||{}),...payload};window.__ucLatestSettings=A.settings;await api('/api/admin/settings',{method:'POST',body:JSON.stringify(A.settings)});window.applyDropBeatAdminBrand?.();window.dispatchEvent(new CustomEvent('uc:brand-updated',{detail:A.settings}));msg('#settingsMsg','Brand settings saved across the website and admin panel.');}
async function saveSocials(e){e.preventDefault();const fd=new FormData(e.target);const base=Object.fromEntries(fd.entries());const socials=[];for(let i=0;i<30;i++){if(base[`social_${i}_key`]){const key=base[`social_${i}_key`];const enabled=fd.get(`social_${i}_enabled`)==='on';const url=(base[`social_${i}_url`]||'').trim()||(enabled?(SOCIAL_DEFAULT_URLS[key]||''):'');socials.push({key,label:base[`social_${i}_label`],url,enabled});}}A.settings={...(A.settings||{}),socials};await api('/api/admin/settings',{method:'POST',body:JSON.stringify(A.settings)});msg('#socialMsg','Social media profiles saved. Front-end footer will update.');}
async function saveTracking(e){e.preventDefault();const payload=Object.fromEntries(new FormData(e.target).entries());A.settings={...(A.settings||{}),...payload};await api('/api/admin/settings',{method:'POST',body:JSON.stringify(A.settings)});msg('#trackingMsg','Tracking info saved. Automation software can also update these values through API Settings.');}
async function bulkPlace(){const ids=qsa('[data-pick-product]:checked').map(x=>Number(x.value));const pages=qsa('[data-place-page]:checked').map(x=>x.value);const section=qs('#placementSection').value||'featured';if(!ids.length||!pages.length)return alert('Select products and pages');const res=await api('/api/admin/placements',{method:'POST',body:JSON.stringify({product_ids:ids,pages,section_key:section})});qs('#placeResult').innerHTML=`<div class="notice">${res.count} placements updated.</div>`;}
async function load_blogs(){const res=await api('/api/admin/blogs');A.blogs=res.posts||[];qs('#blogTable').innerHTML=A.blogs.length?`<table class="table"><thead><tr><th>Fitness Tip</th><th>Status</th><th>Tags</th><th>Actions</th></tr></thead><tbody>${A.blogs.map(p=>`<tr><td><strong>${esc(p.title)}</strong><br><small>${esc(p.slug)}</small></td><td><span class="status ${esc(p.status)}">${esc(p.status)}</span></td><td>${(p.tags||[]).map(t=>`<span class="status">${esc(t)}</span>`).join(' ')}</td><td><button class="btn small" onclick="editBlog(${p.id})">Edit</button> <button class="btn danger small" onclick="deleteBlog(${p.id})">Delete</button></td></tr>`).join('')}</tbody></table>`:'<div class="notice">No Fitness Tips have been loaded yet. Create your first Fitness Tip above.</div>';}
function editBlog(id){const p=A.blogs.find(x=>x.id===id);if(!p)return;const f=qs('#blogForm');f.id.value=p.id;f.title.value=p.title||'';f.slug.value=p.slug||'';f.tags.value=(p.tags||[]).join(', ');f.excerpt.value=p.excerpt||'';f.body_text.value=p.body_text||'';f.cover_image_url.value=p.cover_image_url||'';f.status.value=p.status||'draft';window.scrollTo({top:0,behavior:'smooth'});}
function resetBlogForm(){qs('#blogForm').reset();qs('#blogForm [name="id"]').value='';}
async function saveBlog(e){e.preventDefault();const payload=Object.fromEntries(new FormData(e.target).entries());const res=await api('/api/admin/blogs',{method:'POST',body:JSON.stringify(payload)});msg('#blogMsg',`Fitness Tip saved: ${res.slug}`);resetBlogForm();await load_blogs();}
async function deleteBlog(id){if(!confirm('Delete this Fitness Tip?'))return;await api('/api/admin/blogs?id='+encodeURIComponent(id),{method:'DELETE'});await load_blogs();}
async function load_payments(){const res=await api('/api/admin/integrations');A.payments=res.settings;const s=A.payments;qs('[name="razorpayEnabled"]').checked=!!s.razorpayEnabled;qs('[name="razorpayKeyId"]').value=s.razorpayKeyId||'';qs('#razorpaySecretHint').textContent=s.razorpayKeySecretMasked?`Saved: ${s.razorpayKeySecretMasked}`:'No secret saved yet.';qs('#razorpayWebhookHint').textContent=s.razorpayWebhookSecretMasked?`Saved: ${s.razorpayWebhookSecretMasked}`:'No webhook secret saved yet.';qs('#razorpayWebhookUrl').value=s.razorpayWebhookUrl||'';qs('[name="stripeEnabled"]').checked=!!s.stripeEnabled;qs('[name="stripeFallbackEnabled"]').checked=!!s.stripeFallbackEnabled;qs('[name="stripePublishableKey"]').value=s.stripePublishableKey||'';qs('#stripeSecretHint').textContent=s.stripeSecretKeyMasked?`Saved: ${s.stripeSecretKeyMasked}`:'No secret saved yet.';qs('#stripeWebhookHint').textContent=s.stripeWebhookSecretMasked?`Saved: ${s.stripeWebhookSecretMasked}`:'No webhook secret saved yet.';qs('#stripeWebhookUrl').value=s.stripeWebhookUrl||'';qs('#whatsappWebhookHint').textContent=s.whatsappWebhookVerifyTokenMasked?`Saved: ${s.whatsappWebhookVerifyTokenMasked}`:'No verify token saved yet.';qs('#whatsappWebhookUrl').value=s.whatsappWebhookUrl||'';}
async function savePayments(e){e.preventDefault();const fd=new FormData(e.target);const payload=Object.fromEntries(fd.entries());payload.razorpayEnabled=fd.get('razorpayEnabled')==='on';payload.stripeEnabled=fd.get('stripeEnabled')==='on';payload.stripeFallbackEnabled=fd.get('stripeFallbackEnabled')==='on';const res=await api('/api/admin/integrations',{method:'POST',body:JSON.stringify(payload)});msg('#paymentsMsg',`Payment integration saved. Razorpay plans synced: ${res.syncedPlans||0}. Copy webhook URLs into Razorpay/Stripe dashboards.`);await load_payments();}
async function load_apiSettings(){const res=await api('/api/admin/api-settings');A.api=res;qs('#apiBaseUrl').value=res.apiBaseUrl||'';qs('#vendorUserId').value=res.vendorUserId||'dropbeat-dance-studio';qs('#apiBearerToken').value=res.apiToken||'';qs('#bloggerBlogId').value=res.bloggerBlogId||'';qs('#bloggerApiKey').value=res.bloggerApiKey||'';qs('#authHeaderExample').value=res.apiToken?`Authorization: Bearer ${res.apiToken}`:'';qs('#apiEndpointList').innerHTML=(res.endpoints||[]).map(e=>`<div class="endpoint"><strong>${e.method}</strong><input readonly value="${esc(e.url)}"><button class="btn secondary small" onclick="copyText('${esc(e.url)}')">Copy</button><small>${esc(e.purpose)}</small></div>`).join('');qs('#webhookList').innerHTML=Object.entries(res.webhookEndpoints||{}).map(([k,v])=>`<div class="endpoint"><strong>${esc(k)}</strong><input readonly value="${esc(v)}"><button class="btn secondary small" onclick="copyText('${esc(v)}')">Copy</button></div>`).join('');qs('#apiDocs').innerHTML=`<strong>Required header:</strong> Authorization: Bearer YOUR_API_TOKEN<br><strong>Content-Type:</strong> application/json<br><strong>Vendor User ID:</strong> ${esc(res.vendorUserId||'dropbeat-dance-studio')}<br><br><strong>Blogger note:</strong> Keep Blogger connected through automation software or Google OAuth. POST dance-tip content to /api/automation/blogs or use the Fitness Tips screen manually.`;}
async function saveVendorId(){const vendorUserId=qs('#vendorUserId').value;const bloggerBlogId=qs('#bloggerBlogId')?.value||'';const bloggerApiKey=qs('#bloggerApiKey')?.value||'';await api('/api/admin/api-settings',{method:'POST',body:JSON.stringify({vendorUserId,bloggerBlogId,bloggerApiKey})});msg('#apiMsg','Vendor User ID saved.');await load_apiSettings();}
async function generateApiToken(){if(!confirm('Generate a new API token? Existing automation workflows using the old token will stop working.'))return;await api('/api/admin/api-settings',{method:'POST',body:JSON.stringify({action:'generate',vendorUserId:qs('#vendorUserId').value})});msg('#apiMsg','New API token generated. Copy it now into your automation software.');await load_apiSettings();}
async function revokeApiToken(){if(!confirm('Revoke the API token? automation will stop until a new token is generated.'))return;await api('/api/admin/api-settings',{method:'POST',body:JSON.stringify({action:'revoke'})});msg('#apiMsg','API token revoked.');await load_apiSettings();}
