async function generateOneTimePayment(e){e.preventDefault();const payload=Object.fromEntries(new FormData(e.target).entries());const res=await api('/api/admin/custom-payment',{method:'POST',body:JSON.stringify(payload)});qs('#oneTimePaymentMsg').innerHTML=`<div class="notice"><strong>One-time payment link created.</strong><br>Order ID: ${esc(res.order_id)}<br><div class="copyline"><input id="oneTimePaymentLink" readonly value="${esc(location.origin+res.payment_link)}"><button type="button" class="btn secondary small" onclick="copyValue('oneTimePaymentLink')">Copy Link</button></div>${res.gateway_error?`<small>Gateway note: ${esc(res.gateway_error)}</small>`:''}</div>`;}
