/* Final admin polish overrides - assignment style to avoid duplicate declarations */
googleLoginNotice = async function(){try{const res=await api('/api/portal/google/start?intent=login');location.href=res.authUrl;}catch(e){msg('#loginMsg',e.message,'error');}};
connectGoogleEmail = async function(){try{const res=await api('/api/portal/google/start?intent=connect_admin');location.href=res.authUrl;}catch(e){msg('#googleMsg',e.message,'error');}};
confirmDelete = function(message='This item will be deleted permanently and cannot be recovered.'){
  return new Promise(resolve=>{
    let wrap=qs('#confirmDeleteModal');
    if(!wrap){wrap=document.createElement('div');wrap.id='confirmDeleteModal';wrap.className='modal confirm-modal open';wrap.innerHTML=`<div class="modal-card confirm-card"><h2>Confirm delete</h2><p id="confirmDeleteText"></p><div class="form-actions"><button type="button" class="btn secondary compact preferred" id="confirmCancelBtn">Cancel / Go Back</button><button type="button" class="btn danger compact" id="confirmDeleteBtn">Delete Permanently</button></div></div>`;document.body.appendChild(wrap);} else {wrap.classList.add('open');}
    qs('#confirmDeleteText').textContent=message;
    const done=v=>{wrap.classList.remove('open');resolve(v);};
    qs('#confirmCancelBtn').onclick=()=>done(false);
    qs('#confirmDeleteBtn').onclick=()=>done(true);
  });
};
renderProducts = function(){qs('#productTable').innerHTML=`<table class="table"><thead><tr><th>Plan / Offer</th><th>Price</th><th>Status</th><th>Images</th><th>Actions</th></tr></thead><tbody>${A.products.map(p=>`<tr><td><strong>${esc(p.name)}</strong><br><small>${esc(p.sku)} / ${esc(p.slug)}</small><br><small>${esc(p.short_description||'')}</small></td><td><s>${INR.format((p.regular_price_paise||0)/100)}</s><br><strong>${INR.format((p.offer_price_paise||0)/100)}</strong></td><td><span class="status ${esc(p.status)}">${esc(p.status)}</span></td><td>${(p.images||[]).slice(0,3).map(i=>`<img class="preview-img" src="${esc(i.public_url)}">`).join('')}<br><small>${(p.images||[]).length}/3 images</small></td><td class="action-row"><button class="btn small" onclick="editProductById(${p.id})">Edit</button><button class="btn secondary small" onclick="openMedia(${p.id})">Images</button></td></tr>`).join('')}</tbody></table>`;};
load_placements = async function(){if(!A.products.length){const res=await api('/api/admin/products');A.products=res.products||[];}const box=qs('#placementProductList');if(box)box.innerHTML=A.products.length?A.products.map(p=>`<label class="check"><input data-pick-product type="checkbox" value="${p.id}"> ${esc(p.name)} <small>${esc(p.slug)}</small></label>`).join(''):'<div class="notice">No plans found. Add a plan first.</div>';};
openDashboardList = async function(type){const res=await api('/api/admin/dashboard-list?type='+encodeURIComponent(type));const title={totalLeads:'Total Leads',hotLeads:'Hot Leads',activeSubscriptions:'Active Subscribers',recentLeads:'Recent Leads',pendingCollections:'Pending Collections'}[type]||'Dashboard List';qs('#listModalTitle').textContent=title;const rows=res.rows||[];qs('#dashboardListBox').innerHTML=rows.length?`<div class="list-grid">${rows.map(r=>{const visits=Number(r.visit_count||0);const pages=String(r.visited_pages||'').split(',').filter(Boolean).slice(0,6);return `<div class="lead-card"><h3>${esc(r.name||r.customer_name||r.order_id||'-')}</h3><p class="muted">${esc(r.phone||r.customer_phone||'')} ${r.email||r.customer_email?`• ${esc(r.email||r.customer_email)}`:''}</p>${r.message?`<p>${esc(r.message)}</p>`:''}${visits?`<p><span class="status">${visits} website visits</span></p>`:''}${pages.length?`<p>${pages.map(p=>`<span class="status">${esc(p)}</span>`).join(' ')}</p>`:''}${r.amount_paise?`<p><strong>${INR.format(r.amount_paise/100)}</strong></p>`:''}<small>${esc(r.status||'')} ${r.payment_status?`• ${esc(r.payment_status)}`:''}</small></div>`}).join('')}</div>`:'<div class="notice">No records found yet.</div>';qs('#listModal').classList.add('open');};
renderStories = function(){qs('#storyTable').innerHTML=A.stories.length?`<table class="table clean-actions"><thead><tr><th>Story</th><th>Preview</th><th>Status</th><th>Sort</th><th>Actions</th></tr></thead><tbody>${A.stories.map(s=>`<tr><td><strong>${esc(s.title||'Untitled story')}</strong><br><small>${esc(s.platform)} • ${esc(s.url)}</small></td><td><img class="story-thumb" src="${esc(s.thumbnail_url||'/assets/product-generic.svg')}"></td><td><span class="status ${esc(s.status)}">${esc(s.status)}</span></td><td class="sort-actions"><button class="btn secondary small icon-action" title="Move up" onclick="moveStory(${s.id},-1)">↑</button><button class="btn secondary small icon-action" title="Move down" onclick="moveStory(${s.id},1)">↓</button></td><td class="action-row"><button class="btn secondary small icon-action" title="Edit" onclick="editStory(${s.id})">✎</button><button class="btn danger small icon-action" title="Delete" onclick="deleteStory(${s.id})">×</button></td></tr>`).join('')}</tbody></table>`:'<div class="notice">No success stories added yet.</div>';};
editStory = function(id){const s=A.stories.find(x=>x.id===id);if(!s)return;const f=qs('#successStories form');f.id.value=s.id;f.title.value=s.title||'';f.url.value=s.url||'';f.thumbnail_url.value=s.thumbnail_url||'';f.status.value=s.status||'active';window.scrollTo({top:0,behavior:'smooth'});};
resetStoryForm = function(){const f=qs('#successStories form');if(f)f.reset();const id=qs('#successStories form [name="id"]');if(id)id.value='';};
saveSuccessStory = async function(e){e.preventDefault();const payload=Object.fromEntries(new FormData(e.target).entries());await api('/api/admin/success-stories',{method:'POST',body:JSON.stringify(payload)});resetStoryForm();msg('#storyMsg','Success story saved.');await load_successStories();};
deleteStory = async function(id){if(!await confirmDelete('This success story will be deleted permanently and cannot be recovered.'))return;await api('/api/admin/success-stories?id='+encodeURIComponent(id),{method:'DELETE'});await load_successStories();};
moveStory = async function(id,dir){await api('/api/admin/success-stories',{method:'PUT',body:JSON.stringify({action:'move',id,dir})});await load_successStories();};
load_pages = async function(){const res=await api('/api/admin/pages');A.pages=res.pages||[];A.faqs=res.faqs||[];const labels={home:'Home Page Text',about:'About Us Page',contact:'Contact Us Page',privacy:'Privacy Policy',terms:'Terms & Conditions',refund:'Refund & Cancellation'};qs('#pagesBox').innerHTML=A.pages.map(p=>`<details class="page-editor"><summary>${esc(labels[p.page_key]||p.title)}</summary><input type="hidden" data-page-field="page_key" value="${esc(p.page_key)}"><div class="field"><label>Page Title</label><input data-page-field="title" value="${esc(p.title||'')}"></div><div class="field"><label>Page Content</label><textarea data-page-field="body_text" rows="12">${esc(p.body_text||'')}</textarea><small class="hint">Write normally. The website will format paragraphs automatically.</small></div><div class="form-actions"><button type="button" class="btn compact" onclick="savePage('${esc(p.page_key)}')">Save This Page</button></div><div id="pageMsg_${esc(p.page_key)}"></div></details>`).join('');renderFaqTable();};
pagePayload = function(key){const editor=[...qsa('.page-editor')].find(d=>d.querySelector('[data-page-field="page_key"]')?.value===key);if(!editor)return null;return {type:'page',page_key:key,title:editor.querySelector('[data-page-field="title"]').value,body_text:editor.querySelector('[data-page-field="body_text"]').value};};
savePage = async function(key){const payload=pagePayload(key);if(!payload)return;await api('/api/admin/pages',{method:'POST',body:JSON.stringify(payload)});msg(`#pageMsg_${key}`,'Page saved.');};
saveAllPages = async function(){for(const p of A.pages||[]){const payload=pagePayload(p.page_key);if(payload)await api('/api/admin/pages',{method:'POST',body:JSON.stringify(payload)});}alert('All page edits saved.');await load_pages();};
renderFaqTable = function(){const box=qs('#faqTable');if(!box)return;box.innerHTML=A.faqs.length?`<table class="table clean-actions"><thead><tr><th>Question</th><th>Status</th><th>Sort</th><th>Actions</th></tr></thead><tbody>${A.faqs.map(f=>`<tr><td><strong>${esc(f.question)}</strong></td><td><span class="status ${esc(f.status)}">${esc(f.status)}</span></td><td class="sort-actions"><button class="btn secondary small icon-action" title="Move up" onclick="moveFaq(${f.id},-1)">↑</button><button class="btn secondary small icon-action" title="Move down" onclick="moveFaq(${f.id},1)">↓</button></td><td class="action-row"><button class="btn secondary small icon-action" title="Edit" onclick="editFaq(${f.id})">✎</button><button class="btn danger small icon-action" title="Delete" onclick="deleteFaq(${f.id})">×</button></td></tr>`).join('')}</tbody></table>`:'<div class="notice">No FAQs yet. Add your first FAQ above.</div>';};
editFaq = function(id){const f=A.faqs.find(x=>x.id===id);if(!f)return;const form=qs('#faqForm');form.id.value=f.id;form.question.value=f.question||'';form.answer_text.value=f.answer_text||'';form.status.value=f.status||'active';};
resetFaqForm = function(){qs('#faqForm').reset();qs('#faqForm [name="id"]').value='';};
saveFaq = async function(e){e.preventDefault();const payload=Object.fromEntries(new FormData(e.target).entries());payload.type='faq';await api('/api/admin/pages',{method:'POST',body:JSON.stringify(payload)});resetFaqForm();msg('#faqMsg','FAQ saved.');await load_pages();};
deleteFaq = async function(id){if(!await confirmDelete('This FAQ will be deleted permanently and cannot be recovered.'))return;await api('/api/admin/pages?id='+encodeURIComponent(id),{method:'DELETE'});await load_pages();};
moveFaq = async function(id,dir){await api('/api/admin/pages',{method:'PUT',body:JSON.stringify({type:'faq',action:'move',id,dir})});await load_pages();};
deleteBanner = async function(id){if(!await confirmDelete('This home page banner will be deleted permanently and cannot be recovered.'))return;await api('/api/admin/banners?id='+encodeURIComponent(id),{method:'DELETE'});await load_banners();};
load_banners = async function(){const res=await api('/api/admin/banners');A.banners=res.banners||[];qs('#bannerTable').innerHTML=`<table class="table clean-actions"><thead><tr><th>Home Page Banner</th><th>Image</th><th>Link</th><th>Status</th><th>Actions</th></tr></thead><tbody>${A.banners.map(b=>`<tr><td><strong>${esc(b.title)}</strong><br>${esc(b.subtitle||'')}<br><small>Sort: ${b.sort_order||0}</small></td><td><img class="preview-img" src="${esc(b.desktop_image_url||'/assets/gym-hero.jpg')}"></td><td>${esc(b.link_type)}: ${esc(b.link_value||'')}</td><td><span class="status ${b.visible?'active':'draft'}">${b.visible?'visible':'hidden'}</span></td><td class="action-row"><button class="btn secondary small icon-action" title="Edit" onclick="editBanner(${b.id})">✎</button><button class="btn danger small icon-action" title="Delete" onclick="deleteBanner(${b.id})">×</button></td></tr>`).join('')}</tbody></table>`;};
deleteBlog = async function(id){if(!await confirmDelete('This Fitness Tip will be deleted permanently and cannot be recovered.'))return;await api('/api/admin/blogs?id='+encodeURIComponent(id),{method:'DELETE'});await load_blogs();};
removeProductImage = async function(imageId,productId){if(!await confirmDelete('This product image will be removed and cannot be recovered.'))return;await api('/api/admin/media?image_id='+encodeURIComponent(imageId),{method:'DELETE'});await load_products();await loadProductMedia(productId);};
load_payments = async function(){const res=await api('/api/admin/integrations');A.payments=res.settings;const s=A.payments;qs('[name="razorpayEnabled"]').checked=!!s.razorpayEnabled;qs('[name="razorpayKeyId"]').value=s.razorpayKeyId||'';qs('#razorpaySecretHint').textContent=s.razorpayKeySecretMasked?`(Saved: ${s.razorpayKeySecretMasked})`:'(No secret saved yet.)';qs('#razorpayWebhookHint').textContent=s.razorpayWebhookSecretMasked?`(Saved: ${s.razorpayWebhookSecretMasked})`:'(No webhook secret saved yet.)';qs('#razorpayWebhookUrl').value=s.razorpayWebhookUrl||'';qs('[name="stripeEnabled"]').checked=!!s.stripeEnabled;qs('[name="stripeFallbackEnabled"]').checked=!!s.stripeFallbackEnabled;qs('[name="stripePublishableKey"]').value=s.stripePublishableKey||'';qs('#stripeSecretHint').textContent=s.stripeSecretKeyMasked?`(Saved: ${s.stripeSecretKeyMasked})`:'(No secret saved yet.)';qs('#stripeWebhookHint').textContent=s.stripeWebhookSecretMasked?`(Saved: ${s.stripeWebhookSecretMasked})`:'(No webhook secret saved yet.)';qs('#stripeWebhookUrl').value=s.stripeWebhookUrl||'';qs('#whatsappWebhookHint').textContent=s.whatsappWebhookVerifyTokenMasked?`(Saved: ${s.whatsappWebhookVerifyTokenMasked})`:'(No verify token saved yet.)';qs('#whatsappWebhookUrl').value=s.whatsappWebhookUrl||'';const otpProvider=qs('[name="otpProvider"]');if(otpProvider)otpProvider.value=s.otpProvider||'whatsapp_cloud';const wpid=qs('[name="whatsappPhoneNumberId"]');if(wpid)wpid.value=s.whatsappPhoneNumberId||'';const greenId=qs('[name="greenApiInstanceId"]');if(greenId)greenId.value=s.greenApiInstanceId||'';const wh=qs('#whatsappCloudTokenHint');if(wh)wh.textContent=s.whatsappCloudTokenMasked?`(Saved: ${s.whatsappCloudTokenMasked})`:'(No token saved yet.)';const gh=qs('#greenApiTokenHint');if(gh)gh.textContent=s.greenApiTokenMasked?`(Saved: ${s.greenApiTokenMasked})`:'(No token saved yet.)';};
